#include <graphics.h>
#include <alloc.h>

int main() {
    int gd = DETECT, gm;
    initgraph(&gd, &gm, "C:\\TC\\BGI");
    /* Draw something to save */
    setfillstyle(SOLID_FILL, RED);
    bar(100, 100, 200, 200);
    unsigned size = imagesize(100, 100, 200, 200);
    void *buf = malloc(size);
    getimage(100, 100, 200, 200, buf); /* Save region */
    cleardevice();
    putimage(250, 150, buf, COPY_PUT); /* Restore elsewhere */
    free(buf);
    getch();
    closegraph();
    return 0;
}

